window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[219]={"id":"219","numero":219,"titre":"Pathologie du fer","objectifs":[{"id":"219-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la carence martiale","contenu":"<p>La <span class=\"kw-def\">carence martiale</span> (ou carence en fer) est une <strong>diminution du capital en fer de l'organisme</strong>. C'est le <strong>déficit nutritionnel le plus répandu dans le monde</strong> et la <strong>première cause d'anémie</strong> à l'échelle mondiale. On en distingue <strong>deux types</strong> :</p>\n      <table >\n        <thead><tr><th>&nbsp;</th><th>Carence martiale <strong>absolue</strong></th><th>Carence martiale <strong>fonctionnelle</strong></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Anomalie</strong></td><td>Stocks en fer tissulaire <span class=\"kw-def\">insuffisants</span></td><td><span class=\"kw-bio\">Réserves en fer suffisantes</span> (<span class=\"kw-bio\">ferritine</span> normale) mais <strong>mobilisation du fer vers le pool circulant défaillante</strong></td></tr>\n          <tr><td><strong>Marqueur</strong></td><td><span class=\"kw-bio\">Ferritine sérique</span> &lt; <span class=\"kw-chiffre\">30 µg/L</span> — <strong>affirme à elle seule</strong> la carence absolue</td><td><span class=\"kw-bio\">CST</span> (<span class=\"kw-bio\">coefficient de saturation</span> de la <span class=\"kw-bio\">transferrine</span>) &lt; <span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td><strong>Étiologie principale</strong></td><td><span class=\"kw-etio\">Saignement chronique</span> :<span class=\"kw-chiffre\"> 90 %</span> des carences de l'adulte (pays à haut niveau socio-économique) ; touche <span class=\"kw-chiffre\">25 %</span> des femmes en âge de procréer</td><td><span class=\"kw-etio\">États inflammatoires chroniques</span> (principale) ; <span class=\"kw-etio\">insuffisance rénale</span> ; <span class=\"kw-etio\">insuffisance cardiaque</span> ; <span class=\"kw-etio\">cancers</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Une <span class=\"kw-bio\">ferritine</span> &lt; <span class=\"kw-chiffre\">30 µg/L</span> suffit à affirmer la carence martiale <strong>absolue</strong> ; la carence <strong>fonctionnelle</strong> se définit sur un <span class=\"kw-bio\">CST</span> &lt; <span class=\"kw-chiffre\">20 %</span> avec une <span class=\"kw-bio\">ferritine</span> normale (apport de fer aux précurseurs érythroïdes insuffisant malgré des réserves correctes).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"219-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une surcharge en fer","contenu":"<p>La <span class=\"kw-def\">surcharge en fer</span> est une <strong>accumulation anormale de fer dans l'organisme</strong>, traduite biologiquement par une <span class=\"kw-bio\">hyperferritinémie</span> et, quand elle est viscérale, par une <span class=\"kw-def\">surcharge tissulaire</span> (le <strong>foie stocke <span class=\"kw-chiffre\">70-80 %</span> du fer</strong>).</p>\n      <p><strong>Mécanisme fondamental :</strong> il <span class=\"kw-def\">n'existe aucune voie d'élimination régulée du fer</span>. C'est donc l'<span class=\"kw-def\">absorption intestinale</span> qui conditionne le stockage : toute <strong>dysrégulation de l'absorption</strong> peut conduire à une surcharge.</p>\n      <p><strong>Toxicité :</strong> l'excès de fer catalyse la conversion du <span class=\"kw-bio\">peroxyde d'hydrogène en radicaux libres</span>, qui attaquent les <span class=\"kw-bio\">membranes cellulaires</span>, les <span class=\"kw-bio\">protéines</span> et l'<span class=\"kw-bio\">ADN</span> → dommages tissulaires.</p>\n      <p><strong>Seuils définissant l'hyperferritinémie :</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeurs anormales</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Ferritinémie</span></td><td>Homme &gt; <span class=\"kw-chiffre\">300 µg/L</span> · Femme &gt; <span class=\"kw-chiffre\">200 µg/L</span></td></tr>\n          <tr><td><span class=\"kw-bio\">CST</span> (<span class=\"kw-bio\">coefficient de saturation</span> de la <span class=\"kw-bio\">transferrine</span>)</td><td>Homme &gt; <span class=\"kw-chiffre\">60 %</span> · Femme &gt; <span class=\"kw-chiffre\">50 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le diagnostic de surcharge requiert <strong>toujours le couple <span class=\"kw-bio\">ferritine</span> + CST</strong> : une <span class=\"kw-bio\">hyperferritinémie</span> isolée (<span class=\"kw-bio\">CST</span> normal) n'est <strong>pas</strong> synonyme de surcharge tissulaire (cf. <span class=\"kw-etio\">syndrome inflammatoire</span>, <span class=\"kw-etio\">syndrome métabolique</span>, <span class=\"kw-etio\">cytolyse</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — Cirrhose · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":0},{"id":"219-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principes généraux du métabolisme du fer","contenu":"<p>Le fer est indispensable à l'<span class=\"kw-def\">érythropoïèse</span> (synthèse de l'<span class=\"kw-bio\">hémoglobine</span>), à la <span class=\"kw-def\">myoglobine</span> et à de nombreuses enzymes. Le capital total est d'environ <span class=\"kw-chiffre\">4 à 5 g</span>, dont <span class=\"kw-chiffre\">80 %</span> sous forme <span class=\"kw-bio\">héminique</span> (surtout <span class=\"kw-bio\">hémoglobine</span>, <span class=\"kw-bio\">myoglobine</span>, cytochromes) et <span class=\"kw-chiffre\">20 %</span> sous forme non héminique (<span class=\"kw-bio\">ferritine</span>, <span class=\"kw-bio\">transferrine</span>, hémosidérine du foie, de la rate et des macrophages).</p>\n      <p><strong>Bilan d'entrée / sortie :</strong></p>\n      <ul>\n        <li><strong>Apports alimentaires</strong> faibles : seuls <span class=\"kw-chiffre\">10-20 %</span> des <span class=\"kw-chiffre\">10-25 mg/j</span> ingérés sont absorbés (soit ~<span class=\"kw-chiffre\">1-2 mg/j</span>, au duodénum) ; le <span class=\"kw-bio\">fer héminique</span> (viande) est mieux absorbé que le <span class=\"kw-bio\">fer non héminique</span> (végétaux).</li>\n        <li><strong>Pertes obligatoires non régulées</strong> ~<span class=\"kw-chiffre\">1 mg/j</span> (desquamation digestive et cutanée), majorées à <span class=\"kw-chiffre\">2-3 mg/j</span> par les <span class=\"kw-etio\">menstruations</span> chez la femme.</li>\n      </ul>\n      <p><strong>Acteurs clés du transport et du stockage :</strong></p>\n      <table >\n        <thead><tr><th>Acteur</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">DMT1</span></td><td>Transporteur d'absorption à l'apex de l'entérocyte duodénal (fait entrer le fer ferreux Fe²⁺)</td></tr>\n          <tr><td><span class=\"kw-bio\">Ferroportine</span></td><td>Seul exportateur cellulaire du fer (entérocyte, macrophage) vers le plasma</td></tr>\n          <tr><td><span class=\"kw-bio\">Transferrine</span></td><td>Protéine de <strong>transport plasmatique</strong> du fer ; le <span class=\"kw-bio\">CST</span> reflète sa saturation</td></tr>\n          <tr><td><span class=\"kw-bio\">Ferritine</span></td><td>Protéine de <strong>réserve / stockage</strong> intracellulaire du fer ; reflet du capital martial</td></tr>\n          <tr><td><span class=\"kw-bio\">Hepcidine</span></td><td><strong>Hormone hépatique régulatrice</strong> : bloque la ferroportine → ↓ absorption intestinale + ↓ libération macrophagique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Point clé.</strong> L'<span class=\"kw-bio\">hepcidine</span> est le chef d'orchestre : son <strong>augmentation</strong> (états inflammatoires) séquestre le fer → carence fonctionnelle ; sa <strong>disparition</strong> lève le frein sur la ferroportine → hyperabsorption → <span class=\"kw-def\">hémochromatose</span>. Comme il n'existe <strong>pas d'excrétion régulée</strong>, c'est l'absorption qui équilibre tout le bilan.</div>\n      <p class=\"obj-source\"><em>Principes généraux distillés (métabolisme du fer — Collège de biochimie/hématologie).</em></p>","frequence":1},{"id":"219-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les deux principaux sites anatomiques en cause dans une carence d’absorption du fer (estomac, intestin grêle proximal)","contenu":"<p>L'absorption du fer dépend de <strong>deux sites anatomiques</strong>, dont l'atteinte est responsable des carences martiales par <span class=\"kw-def\">malabsorption</span> :</p>\n      <table >\n        <thead><tr><th>Site</th><th>Rôle dans l'absorption</th><th>Atteintes responsables</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Estomac</span></td><td>L'<strong>acidité gastrique</strong> réduit le fer ferrique (Fe³⁺) en fer ferreux (<strong>Fe²⁺ absorbable</strong>) et le solubilise</td><td><span class=\"kw-etio\">Infection chronique à Helicobacter pylori</span> ; <span class=\"kw-etio\">maladie de Biermer</span> (gastrite atrophique fundique) ; <span class=\"kw-ttt\">IPP au long cours</span> ; <span class=\"kw-etio\">résection / gastrectomie</span></td></tr>\n          <tr><td><span class=\"kw-def\">Intestin grêle proximal</span><br>(duodénum + jéjunum proximal)</td><td><strong>Site principal d'absorption</strong> du fer (entrée par le transporteur <span class=\"kw-bio\">DMT1</span>)</td><td><span class=\"kw-etio\">Maladie cœliaque</span> ; <span class=\"kw-etio\">MICI</span> ; <span class=\"kw-etio\">maladie de Whipple</span> ; <span class=\"kw-etio\">résection duodénale</span> ; <span class=\"kw-ttt\">chirurgie</span> bariatrique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Devant une carence martiale par malabsorption sans saignement, l'<span class=\"kw-bio\">endoscopie digestive haute avec biopsies gastriques et duodénales</span> recherche systématiquement une <span class=\"kw-etio\">maladie cœliaque</span>, une <span class=\"kw-etio\">maladie de Biermer</span> et une <span class=\"kw-etio\">infection à H. pylori</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - gastrite · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique · 282 — MICI</em></p>","frequence":0},{"id":"219-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques de la carence martiale","contenu":"<p>La carence martiale s'exprime par un <span class=\"kw-def\">syndrome anémique</span> (souvent <strong>bien toléré</strong> car d'installation très progressive) et par des signes propres au déficit en fer, qui peuvent exister <strong>même en l'absence d'anémie</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Signes généraux</strong></td><td><span class=\"kw-clinique\">Asthénie</span> (même sans anémie, corrélée à la <span class=\"kw-bio\">ferritine</span>) ; <span class=\"kw-clinique\">fatigabilité musculaire</span> ; <span class=\"kw-clinique\">diminution des performances intellectuelles</span> (troubles de la mémoire, baisse des performances scolaires) ; pâleur cutanéo-muqueuse du syndrome anémique</td></tr>\n          <tr><td><strong>Manifestations cutanéo-muqueuses</strong></td><td><span class=\"kw-clinique\">Koïlonychie</span> : ongles <strong>fins, striés/fendillés, concaves</strong> (carences anciennes)<br><span class=\"kw-clinique\">Rhagades / perlèche</span> : ulcérations des commissures labiales<br><span class=\"kw-clinique\">Alopécie</span> non cicatricielle (sans perte du follicule)<br><span class=\"kw-clinique\">Peau sèche</span> avec <span class=\"kw-clinique\">prurit</span> diffus sine materia<br><span class=\"kw-clinique\">Glossite</span>, <span class=\"kw-clinique\">dysphagie</span> (atrophie de la muqueuse œsophagienne → anneaux de striction)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Comorbidités</span> associées</strong></td><td><span class=\"kw-clinique\">Syndrome des jambes sans repos</span> ; <span class=\"kw-clinique\">PICA</span> (géophagie, attirance pour la terre/le plâtre — à la fois cause et conséquence)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Triade à connaître.</strong> <span class=\"kw-def\">Syndrome de Plummer-Vinson</span> (ou Kelly-Paterson) = <strong>anémie par carence martiale + dysphagie + membranes œsophagiennes</strong>.</div>\n      <div class=\"callout callout-info\"><strong>NB.</strong> Une <span class=\"kw-bio\">thrombocytose réactionnelle</span> (parfois &gt; <span class=\"kw-chiffre\">800 G/L</span>) est fréquente ; la formule leucocytaire reste normale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"219-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d’une surcharge en fer","contenu":"<p>Les signes de surcharge sont surtout ceux de l'<span class=\"kw-def\">hémochromatose</span>. Ils apparaissent tardivement et de façon différée selon le sexe (homme <span class=\"kw-chiffre\">30-50 ans</span> ; femme <strong>après la ménopause</strong>, l'accumulation étant retardée par les menstruations).</p>\n      <div class=\"callout callout-info\"><strong>Règle des « 3 A » — à évoquer devant :</strong> <span class=\"kw-clinique\">Asthénie</span> inexpliquée chronique + <span class=\"kw-clinique\">Arthralgies</span> + élévation des <span class=\"kw-bio\">Aminotransférases (ALAT)</span>.</div>\n      <table >\n        <thead><tr><th>Atteinte</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Articulaire</strong> (précoce, souvent négligée)</td><td><span class=\"kw-clinique\">Poignée de main douloureuse</span> : atteinte des <strong>métacarpo-phalangiennes 2-3</strong> ; arthrose/chondrocalcinose à un <span class=\"kw-clinique\">âge &lt; 50 ans</span> sur sites inhabituels (poignets, chevilles, épaules)</td></tr>\n          <tr><td><strong>Hépatique</strong></td><td><span class=\"kw-clinique\">Hépatomégalie</span> (<span class=\"kw-chiffre\">95 %</span> des symptomatiques) ; élévation des transaminases (<span class=\"kw-bio\">ALAT</span> &lt; 3N) ; <span class=\"kw-clinique\">évolution</span> vers <span class=\"kw-alerte\">cirrhose</span> →<span class=\"kw-chiffre\"> 90 %</span> des décès de l'hémochromatose</td></tr>\n          <tr><td><strong>Endocrinienne</strong></td><td><span class=\"kw-clinique\">Diabète</span> (tardif, insulinopénie par apoptose des cellules β) ; <span class=\"kw-clinique\">hypogonadisme</span> par insuffisance gonadotrope (impuissance)</td></tr>\n          <tr><td><strong>Cardiaque</strong></td><td><span class=\"kw-alerte\">Cardiomyopathie dilatée</span> ou restrictive ; troubles du rythme (notamment <span class=\"kw-clinique\">FA</span>)</td></tr>\n          <tr><td><strong>Cutanée</strong></td><td><span class=\"kw-clinique\">Mélanodermie</span> : coloration grisâtre/brune des téguments (tardive)</td></tr>\n          <tr><td><strong>Osseuse</strong></td><td><span class=\"kw-clinique\">Ostéoporose</span> (indépendante de l'hypogonadisme)</td></tr>\n        </tbody>\n      </table>\n      <p>Tableau historique complet : <span class=\"kw-def\">cirrhose bronzée</span> = mélanodermie + <span class=\"kw-etio\">diabète</span> + <span class=\"kw-clinique\">hépatomégalie</span> + cardiomyopathie + arthralgies.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 279 — Cirrhose · 198 — Arthropathie microcristalline · 128 — Ostéopathie fragilisante</em></p>","frequence":2},{"id":"219-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","contenu":"<p>Chez l'enfant, la carence martiale résulte surtout d'une <span class=\"kw-def\">carence d'apport</span> et/ou d'une <strong>majoration des besoins</strong> liée à la croissance. Plusieurs situations doivent la faire évoquer :</p>\n      <table >\n        <thead><tr><th>Contexte</th><th>Situations évocatrices</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Alimentation du nourrisson</strong></td><td><span class=\"kw-etio\">Allaitement maternel exclusif</span> ou majoritaire <strong>prolongé au-delà de <span class=\"kw-chiffre\">6 mois</span></strong> (lait pauvre en fer) ; <span class=\"kw-etio\">consommation insuffisante de préparations lactées</span> (&lt; 3×/j jusqu'à<span class=\"kw-chiffre\"> 1 an</span>) ; <span class=\"kw-etio\">absence de lait de croissance</span></td></tr>\n          <tr><td><strong>Besoins augmentés</strong></td><td><span class=\"kw-clinique\">Croissance rapide</span> du nourrisson et de l'adolescent ; à l'adolescence chez la fille : <span class=\"kw-etio\">pertes menstruelles</span></td></tr>\n          <tr><td><strong>Réserves initiales insuffisantes</strong></td><td><span class=\"kw-etio\">Prématurité</span> ; <span class=\"kw-etio\">gémellité</span> ; <span class=\"kw-etio\">hypotrophie</span> (constitution incomplète des réserves en fin de <span class=\"kw-ci\">grossesse</span>)</td></tr>\n          <tr><td><strong>Pertes / malabsorption</strong></td><td><span class=\"kw-etio\">Saignement digestif</span> (diverticule de Meckel) ; <span class=\"kw-etio\">maladie cœliaque</span> ; <span class=\"kw-etio\">MICI</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Signaux d'appel.</strong> <span class=\"kw-clinique\">Pâleur</span>, <span class=\"kw-clinique\">asthénie</span>, irritabilité, <span class=\"kw-clinique\">retard / fléchissement des acquisitions</span>, infections à répétition chez un nourrisson au régime lacté déséquilibré.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"219-8","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies d’anomalies des ongles liées à la carence en fer","contenu":"<p>L'atteinte unguéale caractéristique de la <span class=\"kw-def\">carence martiale</span> <strong>ancienne</strong> est la <span class=\"kw-def\">koïlonychie</span>. De nombreuses enzymes des cellules du follicule et du lit unguéal dépendent du <span class=\"kw-bio\">fer</span> ; leur déficit altère la trophicité de l'ongle.</p>\n      <p><strong>Sémiologie à reconnaître sur une photographie :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Ongles fins et cassants</span>, perte du galbe normal.</li>\n        <li><span class=\"kw-clinique\">Stries longitudinales</span>, ongles <span class=\"kw-clinique\">striés / fendillés</span>.</li>\n        <li><span class=\"kw-clinique\">Concavité de la tablette</span> : aspect <span class=\"kw-clinique\">« en cuillère »</span> (<span class=\"kw-def\">koïlonychie</span> vraie), l'ongle pouvant retenir une goutte d'eau.</li>\n        <li>Signes cutanéo-muqueux associés possibles : <span class=\"kw-clinique\">perlèche / rhagades</span>, <span class=\"kw-clinique\">glossite</span>, <span class=\"kw-clinique\">alopécie</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Photo clinique à ajouter.</strong> Aucune photographie d'ongles n'est disponible dans les fiches sources du dossier <code>219/</code> ni dans la banque d'imagerie. Kevin déposera une photo de koïlonychie dans <code>assets/images/219/</code> (B-FIX ultérieur) — la sémiologie ci-dessus reste valable sans l'image.</div>\n      <!-- TODO Kevin : déposer koilonychie-carence-martiale.jpg dans assets/images/219/ -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":0},{"id":"219-9","rang":"B","rubrique":"Contenu multimédia","titre":"Photographies d’un exemple typique de mélanodermie","contenu":"<p>La <span class=\"kw-def\">mélanodermie</span> est un signe cutané <strong>tardif</strong> de la <span class=\"kw-def\">surcharge en fer</span> (<span class=\"kw-def\">hémochromatose</span>). Elle traduit le dépôt de <span class=\"kw-bio\">mélanine</span> et de <span class=\"kw-bio\">fer</span> dans le derme.</p>\n      <p><strong>Sémiologie à reconnaître sur une photographie :</strong></p>\n      <ul>\n        <li>Coloration <span class=\"kw-clinique\">grisâtre / brune</span> ou <span class=\"kw-clinique\">gris-verdâtre</span> des <span class=\"kw-clinique\">téguments</span> (« teint bronzé » permanent, non lié au soleil).</li>\n        <li>Répartition <strong>diffuse</strong>, ou prédominant sur :\n          <ul>\n            <li>les <span class=\"kw-clinique\">zones découvertes</span> (<span class=\"kw-clinique\">visage</span>, <span class=\"kw-clinique\">cou</span>, dos des mains, avant-bras, partie inférieure des jambes) ;</li>\n            <li>les <span class=\"kw-clinique\">parties génitales</span> et la <span class=\"kw-clinique\">muqueuse buccale</span>.</li>\n          </ul>\n        </li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Photo clinique à ajouter.</strong> Aucune photographie de mélanodermie n'est disponible dans les fiches sources du dossier <code>219/</code> ni dans la banque d'imagerie. Kevin déposera une photo typique dans <code>assets/images/219/</code> (B-FIX ultérieur) — la sémiologie ci-dessus reste valable sans l'image.</div>\n      <!-- TODO Kevin : déposer melanodermie-hemochromatose.jpg dans assets/images/219/ -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 279 — Cirrhose</em></p>","frequence":0},{"id":"219-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les paramètres biologiques permettant d’affirmer une carence martiale","contenu":"<p>Le paramètre clé est la <span class=\"kw-bio\">ferritinémie</span> : <strong>premier paramètre à diminuer</strong> et <strong>dernier à se normaliser</strong> après traitement. Une <span class=\"kw-bio\">ferritine</span> &lt; <span class=\"kw-chiffre\">30 µg/L</span> <strong>affirme à elle seule</strong> la carence martiale absolue (les autres dosages sont alors inutiles).</p>\n      <p><strong>Chronologie d'apparition des anomalies biologiques :</strong></p>\n      <ol>\n        <li>↓ <span class=\"kw-bio\">Ferritine</span> (1ᵉ⁠ʳ marqueur ⭐) — suffit au diagnostic.</li>\n        <li>↓ du <span class=\"kw-bio\">CST</span> (<span class=\"kw-bio\">coefficient de saturation</span> de la <span class=\"kw-bio\">transferrine</span>).</li>\n        <li>↑ de la <span class=\"kw-bio\">transferrinémie</span>.</li>\n        <li>↓ du <span class=\"kw-bio\">fer sérique</span>.</li>\n        <li>Puis érythropoïèse ferriprive : <span class=\"kw-bio\">microcytose</span> (après plusieurs mois) → <span class=\"kw-bio\">hypochromie</span> → ↓ de l'<span class=\"kw-bio\">hémoglobine</span> (anémie ferriprive).</li>\n      </ol>\n      <table >\n        <thead><tr><th>Test</th><th>Normale (adulte)</th><th>Déficit sans anémie</th><th>Déficit avec anémie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Ferritine</span> (µg/L)</td><td><span class=\"kw-chiffre\">20-200 (F) / 40-300 (H)</span></td><td>&lt; <span class=\"kw-chiffre\">30</span></td><td>&lt; <span class=\"kw-chiffre\">12</span></td></tr>\n          <tr><td><span class=\"kw-bio\">CST</span> (%)</td><td><span class=\"kw-chiffre\">20-40</span></td><td><span class=\"kw-chiffre\">15-20</span></td><td>&lt; <span class=\"kw-chiffre\">15</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Transferrine</span> (g/L)</td><td><span class=\"kw-chiffre\">1,74-3,82</span></td><td>↑</td><td>↑</td></tr>\n          <tr><td><span class=\"kw-bio\">Fer sérique</span></td><td><span class=\"kw-chiffre\">10-30 µmol/L</span></td><td>N / ↓</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">Hb</span> (g/dL)</td><td>≥ <span class=\"kw-chiffre\">12 (F) / 13 (H)</span></td><td>N</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">VGM</span> (fL)</td><td><span class=\"kw-chiffre\">80-95</span></td><td>N</td><td>&lt; <span class=\"kw-chiffre\">80</span> (microcytaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Pièges d'interprétation.</strong> La <span class=\"kw-bio\">ferritine</span> est une protéine de l'inflammation : un <span class=\"kw-alerte\">syndrome inflammatoire</span> ou une <span class=\"kw-alerte\">insuffisance rénale</span> peuvent la normaliser et masquer une carence (faux négatif). Le <span class=\"kw-alerte\">syndrome néphrotique</span> et l'<span class=\"kw-alerte\">insuffisance hépatique</span> perturbent le bilan en diminuant la <span class=\"kw-bio\">transferrine</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 212 — Hémogramme</em></p>","frequence":3},{"id":"219-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les paramètres biologiques permettant d’affirmer une surcharge en fer","contenu":"<p>Le diagnostic de surcharge repose sur le <strong>couple <span class=\"kw-bio\">ferritinémie</span> + <span class=\"kw-bio\">CST</span></strong> (<span class=\"kw-bio\">coefficient de saturation</span> de la <span class=\"kw-bio\">transferrine</span>). Le <span class=\"kw-bio\">CST</span> est le marqueur le plus sensible et le plus spécifique de l'hémochromatose, avec un <strong>seuil fixe à<span class=\"kw-chiffre\"> 45 %</span></strong>.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-bio\">CST</span></th><th><span class=\"kw-bio\">Ferritine</span></th><th>Interprétation</th></tr></thead>\n        <tbody>\n          <tr><td>&lt; <span class=\"kw-chiffre\">45 %</span></td><td>Normale</td><td>Pas de surcharge en fer</td></tr>\n          <tr><td>&lt; <span class=\"kw-chiffre\">45 %</span></td><td>Élevée</td><td><strong>Exclut l'hémochromatose</strong> → chercher une autre cause : hyperferritinémie sans surcharge (lyse cellulaire, <span class=\"kw-def\">syndrome inflammatoire</span>, éthylisme, syndrome métabolique) ou surcharge à CST normal (<span class=\"kw-etio\">hépatosidérose dysmétabolique / NASH</span>, acéruléoplasminémie)</td></tr>\n          <tr><td>&gt; <span class=\"kw-chiffre\">45 %</span></td><td>Normale</td><td>Rechercher la <span class=\"kw-bio\">mutation C282Y</span> du gène HFE (seuls les homozygotes sont malades)</td></tr>\n          <tr><td>&gt; <span class=\"kw-chiffre\">45 %</span> (surtout &gt; <span class=\"kw-chiffre\">60 %</span>)</td><td>Élevée</td><td>Forte suspicion d'<span class=\"kw-def\">hémochromatose</span> → test <span class=\"kw-etio\">génétique</span> HFE ; si négatif : cirrhose évoluée ou dysérythropoïèse</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant majeur.</strong> Un <span class=\"kw-bio\">CST ≤ 45 %</span> <strong>exclut</strong> l'hémochromatose <span class=\"kw-etio\">génétique</span> (sous réserve d'absence de <span class=\"kw-clinique\">syndrome inflammatoire</span>). À l'inverse, dans l'hémochromatose, le <span class=\"kw-bio\">CST</span> s'élève <strong>avant</strong> la <span class=\"kw-bio\">ferritine</span> (qui ne monte que tardivement).</div>\n      <div class=\"callout callout-info\"><strong>NB.</strong> Ne pas confondre avec la <span class=\"kw-bio\">ferritine glycosylée</span> abaissée de la <strong>maladie de Still</strong> (hyperferritinémie + effondrement de la fraction glycosylée).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 279 — Cirrhose</em></p>","frequence":1},{"id":"219-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les diagnostics différentiels d’une anémie par carence martiale","contenu":"<p>Devant une <span class=\"kw-def\">anémie microcytaire hypochrome</span>, les principaux diagnostics différentiels de la <span class=\"kw-def\">carence martiale</span> sont :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Anémie inflammatoire</span> — <strong>principal <span class=\"kw-def\">diagnostic différentiel</span></strong>.</li>\n        <li><span class=\"kw-etio\">β-thalassémie mineure</span> (trait thalassémique) : <span class=\"kw-bio\">microcytose</span> marquée contrastant avec une anémie modérée, <span class=\"kw-bio\">ferritine</span> normale ou élevée.</li>\n        <li><span class=\"kw-etio\">Saturnisme</span> (intoxication au plomb) : donne rarement une anémie microcytaire.</li>\n      </ul>\n      <p><strong>Distinguer carence martiale, inflammation et anémie mixte sur le <span class=\"kw-bio\">bilan martial</span> :</strong></p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Anémie ferriprive</th><th>Anémie <span class=\"kw-etio\">inflammatoire</span></th><th>Anémie mixte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Ferritine</span></td><td>↓</td><td>↑</td><td>↓, N ou ↑</td></tr>\n          <tr><td><span class=\"kw-bio\">Fer sérique</span></td><td>↓</td><td>↓</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">Transferrine</span></td><td>↑</td><td>↓ (peut être N au début)</td><td>↑, N ou ↓</td></tr>\n          <tr><td><span class=\"kw-bio\">CTF</span> (capacité totale de fixation)</td><td>↑</td><td>↓</td><td>↑, N ou ↓</td></tr>\n          <tr><td><span class=\"kw-bio\">CST</span></td><td>↓</td><td>↓</td><td>↓</td></tr>\n          <tr><td><span class=\"kw-bio\">RsTF</span> (récepteur soluble de la <span class=\"kw-bio\">transferrine</span>)</td><td>↑</td><td>N</td><td>↑</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Clé discriminante.</strong> C'est le <span class=\"kw-bio\">récepteur soluble de la transferrine (RsTF)</span> qui sépare l'<span class=\"kw-etio\">anémie inflammatoire</span> pure (RsTF <strong>normal</strong>) de l'<span class=\"kw-etio\">anémie mixte</span> carence + inflammation (RsTF <strong>augmenté</strong>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 212 — Hémogramme</em></p>","frequence":0},{"id":"219-13","rang":"A","rubrique":"Étiologie","titre":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","contenu":"<p>Quatre grands mécanismes, dont la fréquence varie avec l'âge et le sexe :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Saignement chronique</strong> (1ʳᵉ cause de l'adulte,<span class=\"kw-chiffre\"> 90 %</span>)</td><td><strong>Digestif</strong> : <span class=\"kw-etio\">ulcère</span>, <span class=\"kw-etio\">gastrite</span>, hernie hiatale, <span class=\"kw-etio\">tumeur bénigne ou maligne</span> ⭐, <span class=\"kw-etio\">angiodysplasies</span>, <span class=\"kw-etio\">MICI</span>, diverticule de Meckel, hémorroïdes (diagnostic d'élimination)<br><strong>Gynécologique</strong> : <span class=\"kw-etio\">méno-métrorragies</span>, <span class=\"kw-etio\">fibrome</span>, <span class=\"kw-etio\">cancer de l'endomètre/du col</span>, <span class=\"kw-etio\">endométriose</span>, DIU<br><strong>Autres</strong> : <span class=\"kw-clinique\">hématurie macroscopique</span>, <span class=\"kw-clinique\">épistaxis répétées</span> (Rendu-Osler)</td></tr>\n          <tr><td><strong>Malabsorption</strong></td><td>Résection digestive haute ; <span class=\"kw-etio\">H. pylori</span> ; <span class=\"kw-etio\">maladie de Biermer</span> ; <span class=\"kw-ttt\">IPP</span> au long cours ; <span class=\"kw-etio\">MICI</span> ; <span class=\"kw-etio\">maladie cœliaque</span> ; maladie de Whipple</td></tr>\n          <tr><td><strong>Carence d'apport</strong></td><td>Régime végétarien/végétalien strict, dénutrition ; <strong>nourrisson</strong> : <span class=\"kw-ci\">allaitement</span> exclusif prolongé &gt;<span class=\"kw-chiffre\"> 6 mois</span>, préparations lactées insuffisantes, absence de lait de croissance ; <strong><span class=\"kw-etio\">syndrome des buveurs de thé</span></strong> ; <strong><span class=\"kw-etio\">géophagie</span></strong> — argile la plus fréquemment consommée = <strong><span class=\"kw-etio\">kaolin</span></strong> (vertus pseudo-médicinales, goût, coupe-faim) : à rechercher à l'interrogatoire en nommant explicitement le <span class=\"kw-etio\">kaolin</span> plutôt que « argile »</td></tr>\n          <tr><td><strong>Augmentation des besoins</strong></td><td>Croissance (nourrisson, adolescent) ; <span class=\"kw-etio\">grossesses répétées ou rapprochées</span>, grossesses gémellaires</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Orientation selon le <span class=\"kw-def\">terrain</span> :</strong></p>\n      <ul>\n        <li><strong>Enfant</strong> : carence d'apport et/ou majoration des besoins.</li>\n        <li><strong>Femme non ménopausée</strong> : pertes gynécologiques.</li>\n        <li><strong>Homme et femme ménopausée</strong> : pertes digestives (jusqu'à preuve du contraire).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Pièges à connaître.</strong> Facteurs favorisants : dons du sang répétés, antithrombotiques, consommation excessive de thé. Cause psychiatrique rare : <span class=\"kw-alerte\">syndrome de Lasthénie de Ferjol</span> (pathomimie — spoliation sanguine provoquée, souvent chez un sujet proche du milieu médical).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - gastrite · 301 — Tumeur colon - rectum · 282 — MICI · 41 — Endométriose</em></p>","frequence":1},{"id":"219-14","rang":"B","rubrique":"Étiologie","titre":"Connaître les causes principales d’une surcharge en fer chez l’adulte et chez l’enfant","contenu":"<p>On oppose les surcharges <strong>primitives (génétiques)</strong> et <strong>secondaires (acquises)</strong>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémochromatoses génétiques</strong></td><td><span class=\"kw-etio\">Mutation du gène HFE</span> (&gt;<span class=\"kw-chiffre\"> 95 %</span> — hémochromatose de type 1) ; mutations d'autres gènes plus rares (hepcidine, ferroportine, hémojuvéline, récepteur de la <span class=\"kw-bio\">transferrine</span>)</td></tr>\n          <tr><td><strong>Surcharges secondaires</strong></td><td><span class=\"kw-etio\">Transfusionnelles</span> (<span class=\"kw-etio\">thalassémie</span>, <span class=\"kw-etio\">anémie sidéroblastique</span>, polytransfusion) ; <span class=\"kw-etio\">dysérythropoïèse chronique</span> ; hépatopathies chroniques (<span class=\"kw-etio\">hépatite B/C</span>, <span class=\"kw-etio\">porphyrie cutanée tardive</span>, <span class=\"kw-etio\">hépatopathie alcoolique</span>, <span class=\"kw-etio\">stéatose</span>) ; surcharge alimentaire</td></tr>\n          <tr><td><strong>Hyperferritinémie « sans surcharge » vraie</strong> (CST normal)</td><td><span class=\"kw-etio\">Hépatosidérose dysmétabolique / NASH</span> ; <span class=\"kw-etio\">syndrome métabolique</span> (<span class=\"kw-bio\">ferritine</span> jusqu'à<span class=\"kw-chiffre\"> 800-1500 µg/L</span>) ; <span class=\"kw-etio\">éthylisme chronique</span> ; <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span> ; cytolyse / hémolyse</td></tr>\n          <tr><td><strong>Causes diverses</strong></td><td><span class=\"kw-etio\">Acéruléoplasminémie</span> (CST normal : <span class=\"kw-etio\">diabète</span> + <span class=\"kw-clinique\">syndrome extrapyramidal</span> + ataxie + démence) ; atransferrinémie <span class=\"kw-etio\">congénitale</span> ; hémosidérose africaine (alimentaire)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Particularités de l'enfant.</strong> Les surcharges martiales de l'enfant sont essentiellement décrites chez le <span class=\"kw-etio\">polytransfusé</span> (traitées par chélation). L'hémochromatose <span class=\"kw-etio\">héréditaire</span> se révèle à l'âge adulte → <strong>pas de <span class=\"kw-def\">dépistage</span> systématique avant <span class=\"kw-chiffre\">18 ans</span></strong>.</div>\n      <div class=\"callout callout-warn\"><strong>Saignées <span class=\"kw-ci\">contre-indiquées</span></strong> dans les surcharges sur <span class=\"kw-alerte\">hémopathie / dysérythropoïèse</span> et sur <span class=\"kw-alerte\">éthylisme</span> (anémie, thrombopénie / hypersplénisme) → recourir à la chélation et au traitement de la cause.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 316 — Syndrome myélodysplasique · 279 — Cirrhose · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":0},{"id":"219-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention d’une carence martiale","contenu":"<p>En <strong><span class=\"kw-chiffre\">première intention</span></strong>, le dosage de la <span class=\"kw-bio\">ferritinémie</span> suffit à poser le diagnostic de carence martiale — les autres paramètres ne sont pas nécessaires.</p>\n      <table >\n        <thead><tr><th>Intention</th><th>Bilan</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-bio\">Ferritine</span> seule (1ᵉ⁠ʳ paramètre à diminuer, dernier à se normaliser)</td></tr>\n          <tr><td><strong>2ᵉ intention</strong></td><td>Si <span class=\"kw-bio\">ferritine</span> normale + situation augmentant la <span class=\"kw-bio\">ferritine</span> (<span class=\"kw-alerte\">syndrome inflammatoire</span>, <span class=\"kw-alerte\">insuffisance rénale chronique</span>) : <span class=\"kw-bio\">fer sérique + transferrine</span> (permet le calcul du <span class=\"kw-bio\">CST</span> et de la <span class=\"kw-bio\">CTF</span>). Dosages effectués <strong>à jeun</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Règles de prescription (« à ne pas faire »).</strong>\n        <ul>\n          <li>Pas de dosage <strong>simultané</strong> <span class=\"kw-bio\">ferritine</span> + fer sérique.</li>\n          <li>Pas de <span class=\"kw-bio\">fer sérique</span> si la <span class=\"kw-bio\">ferritine</span> est basse, ni de fer sérique <strong>seul</strong>.</li>\n          <li>Pas de <span class=\"kw-bio\">réticulocytes</span> devant une anémie microcytaire hypochrome ferriprive.</li>\n        </ul>\n      </div>\n      <p><strong>Bilan étiologique</strong> (après confirmation de la carence) :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sujet <span class=\"kw-chiffre\">≥ 40 ans</span></strong></td><td><span class=\"kw-bio\">Endoscopie digestive haute + coloscopie</span> (<span class=\"kw-imagerie\">FOGD</span> + <span class=\"kw-imagerie\">coloscopie</span> avec biopsies) ; si négatives : <span class=\"kw-bio\">vidéo-capsule</span> ou <span class=\"kw-bio\">entéroscopie</span></td></tr>\n          <tr><td><strong>Femme non ménopausée / sujet jeune</strong></td><td>Éliminer une cause <span class=\"kw-etio\">gynécologique</span> ; <span class=\"kw-bio\">endoscopie haute avec biopsies gastriques et duodénales</span> (<span class=\"kw-etio\">cœliaque</span>, <span class=\"kw-etio\">Biermer</span>, <span class=\"kw-etio\">H. pylori</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Interdit.</strong> Pas de recherche de sang dans les selles (<span class=\"kw-alerte\">Haemocult</span>) dans ce contexte — sans valeur ici.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - gastrite · 301 — Tumeur colon - rectum · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique</em></p>","frequence":2},{"id":"219-16","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan de première intention d’une surcharge en fer et les indications de la biopsie hépatique et d’IRM hépatique","contenu":"<p>Devant une <span class=\"kw-bio\">hyperferritinémie</span>, le bilan de <span class=\"kw-chiffre\">première intention</span> élimine d'abord les causes fréquentes, puis caractérise la surcharge.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong> (éliminer les causes fréquentes)</td><td><span class=\"kw-bio\">NFS-réticulocytes</span>, <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-bio\">glycémie à jeun</span>, <span class=\"kw-bio\">bilan lipidique</span> ; <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">haptoglobine</span></td></tr>\n          <tr><td><strong>2ᵉ temps</strong></td><td><span class=\"kw-bio\">CST</span> (peut être dosé avec la <span class=\"kw-bio\">ferritine</span> si surcharge suspectée) ; recherche de la <span class=\"kw-bio\">mutation C282Y</span> du gène HFE <strong>si CST &gt;<span class=\"kw-chiffre\"> 45 %</span></strong></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">IRM hépatique</span> (quantification)</td><td>Hyperferritinémie <strong>inexpliquée</strong> ou avec facteurs confondants ; <strong>quantifie la surcharge hépatique</strong> ; dépiste les complications (<span class=\"kw-alerte\">carcinome hépatocellulaire</span>) ; recommandée si <span class=\"kw-bio\">ferritine &gt; 1000 µg/L</span> ou intrication de facteurs (homozygote C282Y + syndrome métabolique + alcool)</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Ponction-biopsie hépatique</span></td><td><strong>Visée pronostique</strong> : suspicion d'atteinte hépatique sévère (fibrose, cirrhose) ; <strong>visée diagnostique</strong> : anomalie ferrique avec enquête <span class=\"kw-etio\">génétique</span> négative</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Logique.</strong> <span class=\"kw-bio\">Ferritine + CST</span> orientent ; le génotypage HFE confirme l'hémochromatose ; l'<span class=\"kw-imagerie\">IRM</span> remplace largement la <span class=\"kw-ttt\">biopsie</span> pour <strong>quantifier</strong> la surcharge et n'impose la <span class=\"kw-imagerie\">PBH</span> qu'en cas de suspicion de fibrose / d'incertitude diagnostique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — Cirrhose · 304 — Tumeur du foie</em></p>","frequence":3},{"id":"219-17","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens à réaliser en première intention devant une carence martiale chez l’enfant","contenu":"<p>Chez l'enfant, le bilan de <span class=\"kw-chiffre\">première intention</span> de la <span class=\"kw-def\">carence martiale</span> associe l'<span class=\"kw-bio\">hémogramme</span> et la <span class=\"kw-bio\">ferritine</span>, en interprétant les résultats avec la <span class=\"kw-bio\">CRP</span> (pour ne pas méconnaître une carence masquée par l'<span class=\"kw-etio\">inflammation</span>).</p>\n      <ul>\n        <li><span class=\"kw-bio\">NFS-plaquettes</span> : <span class=\"kw-bio\">anémie microcytaire hypochrome</span> (<span class=\"kw-chiffre\">VGM bas</span> pour l'âge), ± <span class=\"kw-bio\">thrombocytose réactionnelle</span> ; formule leucocytaire normale.</li>\n        <li><span class=\"kw-bio\">Ferritinémie</span> : abaissée — affirme la carence martiale (1ᵉ⁠ʳ paramètre à diminuer).</li>\n        <li><span class=\"kw-bio\">CRP</span> : pour interpréter la <span class=\"kw-bio\">ferritine</span> (protéine de l'inflammation).</li>\n        <li>En 2ᵉ intention si doute : <span class=\"kw-bio\">fer sérique + transferrine</span> (<span class=\"kw-bio\">CST</span>), à jeun.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Démarche.</strong> Le diagnostic <span class=\"kw-ttt\">biologique</span> est le même que chez l'adulte (<span class=\"kw-bio\">ferritine</span> + <span class=\"kw-bio\">NFS</span>), mais l'<strong>enquête étiologique</strong> privilégie l'<span class=\"kw-etio\">interrogatoire alimentaire</span> (régime lacté, lait de croissance) avant les explorations invasives, la <span class=\"kw-etio\">carence d'apport</span> étant la cause dominante.</div>\n      <p class=\"obj-source\"><em>Modalités pédiatriques distillées (Collège de pédiatrie).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie · 212 — Hémogramme</em></p>","frequence":0},{"id":"219-18","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la carence martiale chez l’adulte et l’enfant","contenu":"<p>Le traitement repose sur <strong>deux volets indissociables</strong> : <span class=\"kw-ttt\">traiter la cause</span> ++ (retrait d'un DIU, ablation d'un polype, prise en charge d'une ménorragie…) et <strong>recharger les réserves en fer</strong>.</p>\n      <table >\n        <thead><tr><th>Item</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td>Supplémentation par <span class=\"kw-ttt\">voie orale</span> : <strong>sulfate de fer</strong> (sel ferreux) ; alternatives : <span class=\"kw-ttt\">fumarate de fer</span>, <span class=\"kw-ttt\">férédétate de sodium</span>. Traitement pratique et économique</td></tr>\n          <tr><td><strong>Limites</strong></td><td>Absorption intestinale faible (~<span class=\"kw-chiffre\">10 %</span>) → durée prolongée (<strong><span class=\"kw-chiffre\">≥ 3 mois</span></strong>) ; tolérance digestive médiocre (<span class=\"kw-chiffre\">25 %</span>) : <span class=\"kw-clinique\">selles noires</span> ⭐, <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">épigastralgies</span>, <span class=\"kw-clinique\">constipation/diarrhée</span></td></tr>\n          <tr><td><strong>Précautions</strong></td><td><strong>Fractionner les doses</strong> ⭐ ; prise au milieu des repas (améliore l'absorption) ; le <span class=\"kw-ci\">thé</span> et les <span class=\"kw-ci\">gels d'alumine</span> gênent l'absorption ; les compléments alimentaires « riches en fer » ne corrigent pas une carence</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Réponse au traitement et durée :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Crise réticulocytaire</span> à <strong><span class=\"kw-chiffre\">J7</span>-J10</strong> ⭐.</li>\n        <li>Correction de l'<span class=\"kw-bio\">anémie</span> (Hb +<span class=\"kw-chiffre\">1 g/dL</span>/semaine), puis de la microcytose, puis de l'hypochromie.</li>\n        <li>Normalisation de la <span class=\"kw-bio\">ferritinémie</span> en dernier = <strong>critère d'arrêt</strong> ; durée <strong><span class=\"kw-chiffre\">≥ 3 mois</span></strong> (<span class=\"kw-chiffre\">3-6 mois</span>) ; pas de contrôle de la <span class=\"kw-bio\">ferritine</span> avant <span class=\"kw-chiffre\">3 mois</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Non-réponse au traitement (annale ⭐).</strong> Évoquer : <strong>mauvaise observance</strong> ; <span class=\"kw-alerte\">défaut d'absorption</span> (MICI, syndrome IRIDA) ; persistance d'une microcytose à <span class=\"kw-bio\">ferritine</span> normalisée → <span class=\"kw-alerte\">thalassémie hétérozygote</span>. La voie <span class=\"kw-ttt\">IV/IM</span> est réservée à l'<span class=\"kw-ci\">intolérance</span> digestive, l'inefficacité de l'oral, la malabsorption ou la carence profonde.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p>","frequence":4},{"id":"219-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la surcharge en fer","contenu":"<p>Le traitement de référence de l'hémochromatose est la <span class=\"kw-ttt\">saignée</span> (soustraction sanguine). Aucun traitement n'est nécessaire au <strong><span class=\"kw-def\">stade</span> 0-1</strong> (asymptomatique, <span class=\"kw-bio\">ferritine</span> normale) : simple <span class=\"kw-def\">surveillance</span> (tous les <span class=\"kw-chiffre\">1 à 3 ans</span>).</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Principes</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Saignées — induction</strong></td><td>Rythme <strong>hebdomadaire</strong> jusqu'à obtention de l'objectif</td></tr>\n          <tr><td><strong>Saignées — entretien</strong></td><td>Tous les <strong><span class=\"kw-chiffre\">2 à 4 mois</span></strong> selon les patients</td></tr>\n          <tr><td><strong>Objectif</strong></td><td><span class=\"kw-bio\">Ferritine</span> &lt; <span class=\"kw-chiffre\">50 µg/L</span> (si possible CST &lt;<span class=\"kw-chiffre\"> 45 %</span>)</td></tr>\n          <tr><td><strong>Alternatives</strong></td><td><span class=\"kw-ttt\">Érythraphérèse</span> (soustrait plus de GR en 1 fois) ; <span class=\"kw-ttt\">chélateur du fer</span> parentéral (<strong>déféroxamine</strong>) en 2ᵉ intention si CI aux saignées</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indications</span> (temporaires) aux saignées.</strong> <span class=\"kw-ci\">Grossesse</span> ; <span class=\"kw-ci\">Hb &lt; 11 g/dL</span> ; <span class=\"kw-ci\">AOMI sévère</span> ; <span class=\"kw-ci\">FC &lt; 50 ou &gt; 100 bpm</span> ; <span class=\"kw-ci\">PAS &lt; 100 mmHg</span> ; <span class=\"kw-ci\">cardiomyopathie décompensée</span>. Saignées <strong><span class=\"kw-ci\">contre-indiquées</span></strong> aussi dans les surcharges sur hémopathie ou éthylisme (anémie/thrombopénie) → chélation.</div>\n      <p><strong>Mesures associées et selon l'étiologie :</strong></p>\n      <ul>\n        <li>Conseils : <span class=\"kw-ttt\">supprimer l'alcool</span>, <strong>éviter la vitamine C</strong> (favorise l'absorption) ; un régime pauvre en fer n'est pas indiqué.</li>\n        <li><span class=\"kw-etio\">Syndrome métabolique / NASH</span> : perte de poids et correction des troubles métaboliques.</li>\n        <li><span class=\"kw-etio\">Éthylisme</span> : <span class=\"kw-ttt\">sevrage</span> (seul traitement, saignées <span class=\"kw-ci\">contre-indiquées</span>).</li>\n        <li>Atteintes réversibles sous traitement : <span class=\"kw-clinique\">asthénie</span>, mélanodermie, cytolyse, <span class=\"kw-clinique\">hépatomégalie</span>. Atteintes peu/non réversibles : arthralgies, cardiomyopathie (partielle), <span class=\"kw-etio\">diabète</span>, cirrhose, hypogonadisme.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Suivi</span>.</strong> <span class=\"kw-def\">Dépistage</span> systématique du <span class=\"kw-alerte\">carcinome hépatocellulaire</span> tous les semestres (<span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">α-fœtoprotéine</span>). Le suivi du <span class=\"kw-etio\">diabète</span> par <span class=\"kw-bio\">HbA1c</span> est <strong>faussé (abaissé) par les saignées</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 279 — Cirrhose · 316 — Syndrome myélodysplasique</em></p>","frequence":2}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-clinique\">Anémie microcytaire ferriprive</span> chez l'<span class=\"kw-alerte\">homme</span> ou la <span class=\"kw-alerte\">femme ménopausée</span> → <span class=\"kw-etio\">cancer digestif</span> (notamment <span class=\"kw-etio\">colorectal</span>) jusqu'à preuve du contraire → <span class=\"kw-bio\">FOGD + coloscopie</span></li><li><span class=\"kw-def\">Règle des 3 A</span> : <span class=\"kw-clinique\">asthénie</span> chronique inexpliquée + <span class=\"kw-clinique\">arthralgies</span> + élévation des <span class=\"kw-bio\">ALAT</span> → évoquer une <span class=\"kw-def\">hémochromatose</span></li><li><span class=\"kw-bio\">Ferritine &gt; 1000 µg/L</span> → recours au spécialiste + <span class=\"kw-imagerie\">IRM hépatique</span> ; risque de <span class=\"kw-alerte\">fibrose / cirrhose</span></li><li><span class=\"kw-alerte\">Cirrhose</span> (HTP, <span class=\"kw-alerte\">insuffisance hépatocellulaire</span>) = <span class=\"kw-chiffre\">90 %</span> des décès de l'hémochromatose ; dépister le <span class=\"kw-alerte\">carcinome hépatocellulaire</span></li><li><span class=\"kw-alerte\">Cardiomyopathie</span> dilatée ou restrictive + <span class=\"kw-clinique\">troubles du rythme</span> (<span class=\"kw-clinique\">FA</span>) de la surcharge en fer</li><li><span class=\"kw-alerte\">Syndrome de Lasthénie de Ferjol</span> (pathomimie) : spoliation sanguine provoquée, à évoquer chez un sujet proche du milieu médical</li></ul>","principes":"<p>Dans les deux pathologies, <strong>traiter la cause</strong> est prioritaire : recharge martiale + correction de la source des pertes pour la carence ; déplétion en fer + traitement étiologique pour la surcharge.</p><p><strong>Carence martiale <span class=\"q\">— recharge orale (adulte et enfant)</span></strong></p><p><span class=\"kw-bio\">Crise réticulocytaire</span> à <span class=\"kw-chiffre\">J7-J10</span> ⭐ ; normalisation de la <span class=\"kw-bio\">ferritine</span> = critère d'arrêt</p><ul><li><strong>Traiter la cause ++</strong> : <span class=\"kw-etio\">retrait d'un DIU</span>, <span class=\"kw-etio\">ablation d'un polype</span>, prise en charge d'une <span class=\"kw-etio\">ménorragie</span></li><li><span class=\"kw-ttt\">Sel ferreux oral</span> en 1ʳᵉ intention (<span class=\"kw-ttt\">sulfate de fer</span> ; alternatives : <span class=\"kw-ttt\">fumarate de fer</span>, <span class=\"kw-ttt\">férédétate de sodium</span>)</li><li>Durée <span class=\"kw-chiffre\">≥ 3 mois</span> (<span class=\"kw-chiffre\">3-6 mois</span>) — absorption intestinale faible (~<span class=\"kw-chiffre\">10 %</span>)</li><li><strong>Fractionner les doses</strong> ⭐, prise au milieu des repas ; <span class=\"kw-ci\">thé</span> et <span class=\"kw-ci\">gels d'alumine</span> gênent l'absorption</li><li>Voie <span class=\"kw-ttt\">IV / IM</span> réservée : <span class=\"kw-ci\">intolérance</span> digestive, inefficacité de l'oral, <span class=\"kw-etio\">malabsorption</span> ou carence profonde</li></ul><p><strong>Surcharge en fer <span class=\"q\">— hémochromatose</span></strong></p><p><span class=\"kw-ci\">CI temporaires aux saignées</span> : <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-ci\">Hb &lt; 11 g/dL</span>, <span class=\"kw-ci\">AOMI sévère</span>, <span class=\"kw-ci\">FC &lt; 50 ou &gt; 100 bpm</span>, <span class=\"kw-ci\">PAS &lt; 100 mmHg</span>, <span class=\"kw-ci\">cardiomyopathie décompensée</span></p><ul><li>Aucun traitement au <span class=\"kw-def\">stade 0-1</span> (asymptomatique, <span class=\"kw-bio\">ferritine</span> normale) → <span class=\"kw-def\">surveillance</span> tous les <span class=\"kw-chiffre\">1 à 3 ans</span></li><li><span class=\"kw-ttt\">Saignées</span> (traitement de référence) : induction <strong>hebdomadaire</strong> puis entretien tous les <span class=\"kw-chiffre\">2 à 4 mois</span></li><li>Objectif : <span class=\"kw-bio\">ferritine &lt; 50 µg/L</span> (si possible <span class=\"kw-bio\">CST &lt; 45 %</span>)</li><li>Alternatives : <span class=\"kw-ttt\">érythraphérèse</span> ; <span class=\"kw-ttt\">chélateur du fer</span> parentéral (<span class=\"kw-ttt\">déféroxamine</span>) en 2ᵉ intention si CI</li><li>Mesures : <span class=\"kw-ttt\">supprimer l'alcool</span>, <span class=\"kw-ci\">éviter la vitamine C</span> ; régime pauvre en fer non indiqué</li></ul><p><strong>Surcharges secondaires <span class=\"q\">— traitement étiologique</span></strong></p><p>Chez l'enfant, surcharge surtout décrite chez le <span class=\"kw-etio\">polytransfusé</span> → chélation ; pas de <span class=\"kw-def\">dépistage</span> de l'hémochromatose avant <span class=\"kw-chiffre\">18 ans</span></p><ul><li><span class=\"kw-etio\">Éthylisme</span> : <span class=\"kw-ttt\">sevrage</span> = seul traitement (<span class=\"kw-ci\">saignées contre-indiquées</span> : anémie / thrombopénie)</li><li><span class=\"kw-etio\">Syndrome métabolique / NASH</span> : <span class=\"kw-ttt\">perte de poids</span> et correction des troubles métaboliques</li><li><span class=\"kw-etio\">Hémopathie / dysérythropoïèse</span> polytransfusée : <span class=\"kw-ttt\">chélation du fer</span> (<span class=\"kw-ci\">saignées contre-indiquées</span>)</li></ul>","suivi":"<p><strong>Carence martiale</strong></p><p>Non-réponse ⭐ : <strong>mauvaise observance</strong>, <span class=\"kw-alerte\">défaut d'absorption</span> (<span class=\"kw-etio\">MICI</span>, syndrome <span class=\"kw-etio\">IRIDA</span>), ou <span class=\"kw-etio\">thalassémie hétérozygote</span> si microcytose persistante à <span class=\"kw-bio\">ferritine</span> normalisée</p><ul><li>Pas de contrôle de la <span class=\"kw-bio\">ferritine</span> avant <span class=\"kw-chiffre\">3 mois</span> ; normalisation de la <span class=\"kw-bio\">ferritine</span> = critère d'arrêt (durée <span class=\"kw-chiffre\">≥ 3 mois</span>)</li><li>Ordre de correction : <span class=\"kw-bio\">anémie</span> (Hb +<span class=\"kw-chiffre\">1 g/dL</span>/sem) → microcytose → hypochromie → <span class=\"kw-bio\">ferritine</span> en dernier</li></ul><p><strong>Surcharge / hémochromatose</strong></p><p><span class=\"kw-def\">Dépistage familial</span> (rang C) : apparentés du 1ᵉ⁠ʳ degré, chez l'adulte <span class=\"kw-chiffre\">&gt; 18 ans</span></p><ul><li><span class=\"kw-def\">Surveillance</span> des <span class=\"kw-ttt\">saignées</span> : éviter une <span class=\"kw-alerte\">anémie</span>, suivre la décroissance de la <span class=\"kw-bio\">ferritine</span></li><li><span class=\"kw-def\">Dépistage</span> systématique du <span class=\"kw-alerte\">carcinome hépatocellulaire</span> tous les semestres : <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">α-fœtoprotéine</span></li><li><span class=\"kw-bio\">HbA1c</span> <strong>faussée (abaissée)</strong> par les saignées → ne pas l'utiliser seule pour le <span class=\"kw-def\">suivi</span> du <span class=\"kw-clinique\">diabète</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/haemochromatosis","label":"Radiopaedia : Haemochromatosis"},{"href":"https://radiopaedia.org/articles/steatotic-liver-disease","label":"Radiopaedia : Steatotic liver disease"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hyperferritinémie confirmée — coefficient de saturation de la transferrine (CST) ? — Seuil discriminant fixe à 45 % (marqueur le plus sensible et spécifique)","detail":"<h4>CAT — orientation étiologique d'une hyperferritinémie — Le couple <span class=\"kw-bio\">ferritine</span> + CST oriente toute la démarche</h4>","branches":[{"to":"q-surcharge","label":"CST ≤ 45 % — hémochromatose génétique exclue","color":"blue"},{"to":"q-hfe","label":"CST > 45 % — hémochromatose suspectée (surtout > 60 %)","color":"amber"}]},{"id":"q-surcharge","kind":"decision","label":"Surcharge tissulaire vraie à l'IRM hépatique ? — CST ≤ 45 % exclut l'hémochromatose primitive (hors syndrome inflammatoire)","branches":[{"to":"t-sans-surcharge","label":"Non — pas de surcharge tissulaire","color":"amber"},{"to":"t-cst-normal","label":"Oui — surcharge confirmée à CST normal","color":"amber"}]},{"id":"t-sans-surcharge","kind":"terminal","label":"Hyperferritinémie sans surcharge","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">IRM hépatique</span> sans surcharge : <span class=\"kw-bio\">ferritine</span> élevée mais pas de fer tissulaire en excès</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">ferritine</span> = protéine de l'inflammation)</li><li><span class=\"kw-etio\">Cytolyse / lyse cellulaire</span> : hépatique, hémolyse, rhabdomyolyse</li><li><span class=\"kw-etio\">Éthylisme chronique</span></li><li><span class=\"kw-etio\">Syndrome métabolique</span> (<span class=\"kw-bio\">ferritine</span> jusqu'à <span class=\"kw-chiffre\">800-1500 µg/L</span>)</li><li><span class=\"kw-etio\">Syndrome d'activation macrophagique</span>, <span class=\"kw-etio\">maladie de Gaucher</span>, <span class=\"kw-etio\">cancers / hémopathies</span></li></ul><h4>Piège</h4><ul><li>Ne pas confondre avec la <span class=\"kw-bio\">ferritine glycosylée</span> effondrée de la <span class=\"kw-def\">maladie de Still</span></li></ul><h4>Conduite</h4><ul><li>Traiter la <span class=\"kw-etio\">cause</span> ; <span class=\"kw-ci\">pas de saignées</span></li></ul>"},{"id":"t-cst-normal","kind":"terminal","label":"Surcharge en fer à CST normal","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">IRM hépatique</span> confirmant la <span class=\"kw-def\">surcharge tissulaire</span> malgré un <span class=\"kw-bio\">CST</span> normal</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Hépatosidérose dysmétabolique / NASH</span> : insulinorésistance, <span class=\"kw-bio\">↑ ALAT + γGT</span> + hyperferritinémie, <span class=\"kw-imagerie\">foie hyperéchogène</span></li><li><span class=\"kw-etio\">Acéruléoplasminémie héréditaire</span> : <span class=\"kw-clinique\">diabète</span> + <span class=\"kw-clinique\">syndrome extrapyramidal</span> + <span class=\"kw-clinique\">ataxie</span> + <span class=\"kw-clinique\">démence</span></li></ul><h4>Conduite (NASH)</h4><ul><li><span class=\"kw-ttt\">Perte de poids</span> et correction des troubles métaboliques ; surcharge susceptible d'évoluer vers <span class=\"kw-alerte\">fibrose / cirrhose</span></li></ul><h4>Renvoi</h4><ul><li>Item 279 (cirrhose) · Item 247 (<span class=\"kw-etio\">diabète</span>)</li></ul>"},{"id":"q-hfe","kind":"decision","label":"Génotypage HFE : homozygote C282Y (ou hétérozygote composite C282Y/H63D) ? — Recherche de la mutation C282Y du gène HFE, après consentement écrit","branches":[{"to":"t-hemochromatose","label":"Positif — mutation HFE confirmante","color":"red"},{"to":"t-hfe-neg","label":"Négatif — pas de mutation HFE confirmante","color":"blue"}]},{"id":"t-hemochromatose","kind":"terminal","label":"Hémochromatose génétique (type 1)","color":"red","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-bio\">Homozygotie C282Y +/+</span> (ou <span class=\"kw-bio\">hétérozygote composite C282Y/H63D</span>) du gène HFE ; type 1 = &gt; <span class=\"kw-chiffre\">95 %</span> des cas</li></ul><h4>Bilan de retentissement</h4><ul><li><span class=\"kw-def\">Stadification</span> clinique + <span class=\"kw-bio\">ferritine</span> ; bilan indispensable dès le <span class=\"kw-def\">stade 2</span></li><li><span class=\"kw-bio\">Glycémie à jeun</span> ; <span class=\"kw-imagerie\">ECG</span> (± <span class=\"kw-imagerie\">ETT</span> stades 3-4)</li><li><span class=\"kw-bio\">Transaminases</span> + <span class=\"kw-imagerie\">échographie hépatique</span> ; <span class=\"kw-bio\">testostérone</span> chez l'homme</li><li><span class=\"kw-bio\">Ferritine &gt; 1000 µg/L</span> → <span class=\"kw-imagerie\">IRM hépatique</span> + recours spécialiste ; <span class=\"kw-imagerie\">PBH</span> si suspicion de fibrose</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Saignées</span> : induction hebdomadaire → entretien tous les <span class=\"kw-chiffre\">2 à 4 mois</span> (objectif <span class=\"kw-bio\">ferritine &lt; 50 µg/L</span>)</li><li><span class=\"kw-ttt\">Érythraphérèse</span> ou <span class=\"kw-ttt\">déféroxamine</span> si CI aux saignées ; <span class=\"kw-ttt\">supprimer l'alcool</span>, <span class=\"kw-ci\">éviter la vitamine C</span></li></ul><h4><span class=\"kw-def\">Suivi</span></h4><ul><li><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-alerte\">carcinome hépatocellulaire</span> tous les semestres (<span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">α-fœtoprotéine</span>) ; dépistage familial des apparentés du 1ᵉ⁠ʳ degré &gt; <span class=\"kw-chiffre\">18 ans</span></li></ul><h4>Renvoi</h4><ul><li>Item 247 (<span class=\"kw-etio\">diabète</span>) · Item 279 (cirrhose)</li></ul>"},{"id":"t-hfe-neg","kind":"terminal","label":"HFE négatif — autres surcharges","color":"blue","detail":"<h4>Interprétation</h4><ul><li>Génotypage négatif (hétérozygote simplex C282Y ou H63D, ou absence de mutation) ; un <span class=\"kw-bio\">CST &gt; 45 %</span> est rarement négatif si &gt; <span class=\"kw-chiffre\">65 %</span></li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Cirrhose hépatique évoluée</span> ; <span class=\"kw-etio\">dysérythropoïèse chronique</span></li><li><span class=\"kw-etio\">Surcharges secondaires transfusionnelles</span> : thalassémie, anémie sidéroblastique, polytransfusé</li><li><span class=\"kw-etio\">Hépatopathies chroniques</span> : hépatite B/C, porphyrie cutanée tardive, hépatopathie alcoolique, stéatose</li></ul><h4>Conduite</h4><ul><li>Forte suspicion persistante → tests génétiques de 2ᵉ intention (hémochromatose juvénile, récepteur de la <span class=\"kw-bio\">transferrine</span>) + <span class=\"kw-imagerie\">PBH</span> ; <span class=\"kw-ttt\">chélation</span> si surcharge transfusionnelle (<span class=\"kw-ci\">saignées CI</span> en cas d'anémie / hémopathie)</li></ul><h4>Renvoi</h4><ul><li>Item 279 (cirrhose) · Item 316 (syndrome myélodysplasique)</li></ul>"}]},"cards":[{"i":"77790fd2d3bf","n":219,"o":"219-1","u":"Définition","t":"Connaître la définition de la carence martiale","q":"Quels sont les marqueurs biologiques permettant de diagnostiquer une carence martiale absolue ou fonctionnelle, selon le contenu source ?","a":"<ul><li>Une <strong>ferritine sérique &lt; 30 µg/L</strong> affirme à elle seule la <strong>carence martiale absolue</strong>.</li><li>Un <strong>coefficient de saturation de la transferrine (CST) &lt; 20 %</strong>, avec une ferritine normale, est le marqueur de la <strong>carence martiale fonctionnelle</strong>.</li></ul>"},{"i":"d17e13a2e0de","n":219,"o":"219-1","u":"Définition","t":"Connaître la définition de la carence martiale","q":"Comment distingue-t-on la carence martiale absolue de la carence martiale fonctionnelle ?","a":"<ul><li>La <strong>carence martiale absolue</strong> correspond à des <strong>stocks en fer tissulaire insuffisants</strong>.</li><li>La <strong>carence martiale fonctionnelle</strong> se caractérise par des <strong>réserves en fer suffisantes</strong> (ferritine normale) mais une <strong>mobilisation défaillante</strong> vers le pool circulant.</li></ul>"},{"i":"fd7648ef20d8","n":219,"o":"219-1","u":"Définition","t":"Connaître la définition de la carence martiale","q":"Quelle est la définition générale de la carence martiale ?","a":"<p>La carence martiale, ou carence en fer, est une <strong>diminution du capital en fer</strong> de l'organisme. C'est le <strong>déficit nutritionnel le plus répandu</strong> et la <strong>première cause d'anémie</strong> au niveau mondial.</p>"},{"i":"875b3bf649c0","n":219,"o":"219-10","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une carence martiale","q":"Décrivez la chronologie d'apparition des anomalies biologiques en cas de carence martiale.","a":"<ul><li>D'abord, diminution de la <strong>ferritinémie</strong> (marqueur le plus précoce).</li><li>Ensuite, diminution du <strong>coefficient de saturation de la transferrine (CST)</strong>.</li><li>Puis, augmentation de la <strong>transferrinémie</strong> et diminution du <strong>fer sérique</strong>.</li><li>Enfin, en cas d'érythropoïèse ferriprive, apparition d'une <strong>microcytose</strong> (plusieurs mois après), suivie d'une <strong>hypochromie</strong>, puis d'une diminution de l'<strong>hémoglobine</strong> (anémie ferriprive).</li></ul>"},{"i":"be69c85e0193","n":219,"o":"219-10","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une carence martiale","q":"Quel est le paramètre biologique clé pour le diagnostic positif d'une carence martiale et pourquoi ?","a":"<p>Le paramètre clé est la <strong>ferritinémie</strong>. C'est le premier paramètre à diminuer en cas de carence martiale et le dernier à se normaliser après traitement.</p>"},{"i":"c7bb5c5dc98c","n":219,"o":"219-10","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une carence martiale","q":"Quels pièges d'interprétation doivent être connus concernant la ferritinémie dans le diagnostic d'une carence martiale ?","a":"<p>La ferritine est une protéine de l'inflammation. Un <strong>syndrome inflammatoire</strong> ou une <strong>insuffisance rénale</strong> peuvent normaliser la ferritinémie et masquer une carence martiale (faux négatif).</p>"},{"i":"e5518df07d78","n":219,"o":"219-10","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une carence martiale","q":"Quelle valeur de ferritinémie permet d'affirmer à elle seule une carence martiale absolue ?","a":"<p>Une ferritinémie <strong>inférieure à 30 µg/L</strong> affirme à elle seule la carence martiale absolue.</p>"},{"i":"107ec494f113","n":219,"o":"219-11","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une surcharge en fer","q":"Quel paramètre biologique est le marqueur le plus sensible et spécifique de l'hémochromatose, et quel est son seuil diagnostique ?","a":"<p>Le <strong>Coefficient de Saturation de la Transferrine (CST)</strong> est le marqueur le plus sensible et spécifique de l'hémochromatose. Son seuil diagnostique est un CST <strong>fixé à 45 %</strong>.</p>"},{"i":"2b568ae940e8","n":219,"o":"219-11","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une surcharge en fer","q":"Comment interpréter un CST &lt; 45 % lorsque la ferritinémie est élevée dans le contexte d'une suspicion de surcharge en fer ?","a":"<p>Un CST &lt; 45 % avec une ferritinémie élevée exclut une hémochromatose génétique HFE (sous réserve d'absence de syndrome inflammatoire). Il faut alors rechercher une autre cause d'hyperferritinémie telle qu'une <strong>lyse cellulaire</strong>, un <strong>syndrome inflammatoire</strong>, un <strong>éthylisme</strong>, un <strong>syndrome métabolique</strong>, ou une surcharge avec CST normal (<strong>hépatosidérose dysmétabolique / NASH</strong>, acéruléoplasminémie).</p>"},{"i":"5e294015635b","n":219,"o":"219-11","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une surcharge en fer","q":"Quel diagnostic faut-il fortement suspecter en présence d'un CST &gt; 45 % (surtout &gt; 60 %) et d'une ferritinémie élevée, et quel est l'examen complémentaire indiqué ?","a":"<p>Il faut fortement suspecter une <strong>hémochromatose</strong>. L'examen complémentaire indiqué est le <strong>test génétique HFE</strong>.</p>"},{"i":"afe8fed1fe4d","n":219,"o":"219-11","u":"Diagnostic positif","t":"Connaître les paramètres biologiques permettant d’affirmer une surcharge en fer","q":"Quels sont les deux paramètres biologiques clés permettant d'affirmer une surcharge en fer ?","a":"<p>Les deux paramètres biologiques clés sont la <strong>ferritinémie</strong> et le <strong>Coefficient de Saturation de la Transferrine (CST)</strong>.</p>"},{"i":"016e5fa55e37","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quels sont les facteurs favorisants et les pièges étiologiques à connaître dans la carence martiale ?","a":"<ul><li>Les <strong>facteurs favorisants</strong> sont : les <strong>dons du sang répétés</strong>, la prise d'<strong>antithrombotiques</strong>, une consommation excessive de thé.</li><li>Un piège rare est le <strong>syndrome de Lasthénie de Ferjol</strong> (pathomimie, spoliation sanguine provoquée, souvent chez un sujet proche du milieu médical).</li></ul>"},{"i":"14ec20314ed6","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quels sont les quatre grands mécanismes étiologiques d'une carence martiale chez l'adulte et l'enfant ?","a":"<p>Les quatre grands mécanismes sont :</p><ul><li>Le <strong>saignement chronique</strong></li><li>La <strong>malabsorption</strong></li><li>La <strong>carence d'apport</strong></li><li>L'<strong>augmentation des besoins</strong></li></ul>"},{"i":"637ad4bf82e6","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quelles sont les principales causes de malabsorption du fer ?","a":"<p>Les principales causes de malabsorption du fer sont :</p><ul><li><strong>Résection digestive haute</strong></li><li>Infection à <em><strong>Helicobacter pylori</strong></em></li><li>Maladie de Biermer</li><li>Prise prolongée d'<strong>IPP</strong> (inhibiteurs de la pompe à protons)</li><li>MICI (maladies inflammatoires chroniques de l'intestin)</li><li>Maladie cœliaque</li><li>Maladie de Whipple</li></ul>"},{"i":"78826aaa4738","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quelles sont les causes de carence d'apport et d'augmentation des besoins en fer, notamment chez l'enfant ?","a":"<ul><li>Les causes de <strong>carence d'apport</strong> sont : régime végétarien/végétalien strict, dénutrition, allaitement exclusif prolongé <strong>> 6 mois</strong> sans supplémentation chez le nourrisson, préparations lactées insuffisantes, absence de lait de croissance.</li><li>Les causes d'<strong>augmentation des besoins</strong> sont : la <strong>croissance</strong> (nourrisson, adolescent), les <strong>grossesses répétées ou rapprochées</strong>, les grossesses gémellaires.</li></ul>"},{"i":"8e9a1a614d0c","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quelle est l'orientation étiologique d'une carence martiale selon le terrain chez l'adulte ?","a":"<ul><li>Chez la <strong>femme non ménopausée</strong> : il faut rechercher en priorité des <strong>pertes gynécologiques</strong>.</li><li>Chez l'<strong>homme et la femme ménopausée</strong> : il faut suspecter des <strong>pertes digestives</strong> jusqu'à preuve du contraire.</li></ul>"},{"i":"953136ee299a","n":219,"o":"219-13","u":"Étiologie","t":"Connaître les causes principales d’une carence martiale chez l’adulte et chez l’enfant","q":"Quelles sont les causes principales de saignement chronique entraînant une carence martiale chez l'adulte ?","a":"<p>Les causes principales de saignement chronique sont :</p><ul><li><strong>Digestives</strong> : ulcère, gastrite, hernie hiatale, <strong>tumeur bénigne ou maligne</strong>, angiodysplasies, MICI, diverticule de Meckel, hémorroïdes.</li><li><strong>Gynécologiques</strong> : méno-métrorragies (première cause chez la femme non ménopausée), fibrome, cancer de l'endomètre/du col, endométriose, DIU.</li><li><strong>Autres</strong> : hématurie macroscopique, épistaxis répétées (syndrome de Rendu-Osler).</li></ul>"},{"i":"2096f3e5cc42","n":219,"o":"219-15","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une carence martiale","q":"Quels sont les pièges et les erreurs à éviter lors de la prescription du bilan martial de première intention ?","a":"<ul><li>Ne pas doser simultanément la ferritine et le fer sérique.</li><li>Ne pas doser le fer sérique seul.</li><li>Ne pas doser le fer sérique si la ferritinémie est basse.</li><li>Ne pas rechercher de réticulocytes devant une anémie microcytaire hypochrome ferriprive avérée.</li></ul>"},{"i":"9397cc063192","n":219,"o":"219-15","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une carence martiale","q":"Quand réalise-t-on d'autres examens biologiques que la ferritinémie dans le bilan d'une carence martiale et lesquels ?","a":"<p>Des examens complémentaires (fer sérique et transferrine, permettant le calcul du coefficient de saturation de la transferrine (CST) et de la capacité totale de fixation (CTF)) sont réalisés si la ferritinémie est normale dans un contexte de syndrome inflammatoire ou d'insuffisance rénale chronique. Ces dosages doivent être effectués <strong>à jeun</strong>.</p>"},{"i":"93d6d4c7e467","n":219,"o":"219-15","u":"Examens complémentaires","t":"Connaître le bilan de première intention d’une carence martiale","q":"Quel est l'examen clé de première intention pour le diagnostic d'une carence martiale ?","a":"<p>L'examen clé de première intention pour le diagnostic d'une carence martiale est le dosage de la <strong>ferritinémie</strong>.</p>"},{"i":"1f65191527e3","n":219,"o":"219-18","u":"Prise en charge","t":"Connaître les principes du traitement de la carence martiale chez l’adulte et l’enfant","q":"Quel est le traitement de première intention de la carence martiale et quelles sont ses limites ?","a":"Le traitement de première intention est la <strong>supplémentation orale en fer</strong>, généralement avec du <strong>sulfate de fer</strong> (sel ferreux), du fumarate de fer ou du férédétate de sodium. Ses principales limites sont :\n<ul>\n  <li>Une <strong>absorption intestinale faible</strong> (~10%), nécessitant une durée de traitement prolongée (≥ 3 mois).</li>\n  <li>Une <strong>tolérance digestive médiocre</strong> chez environ 25% des patients (symptômes incluent selles noires, nausées, épigastralgies, constipation/diarrhée).</li>\n</ul>"},{"i":"672fa882781f","n":219,"o":"219-18","u":"Prise en charge","t":"Connaître les principes du traitement de la carence martiale chez l’adulte et l’enfant","q":"Quelles sont les précautions à prendre et les signes de réponse au traitement martial oral ?","a":"Les précautions incluent de <strong>fractionner les doses</strong>, de prendre le fer <strong>au milieu des repas</strong> pour améliorer la tolérance (mais potentiellement réduire légèrement l'absorption), et d'éviter simultanément le thé et les gels d'alumine qui gênent l'absorption. La réponse au traitement est marquée par :\n<ul>\n  <li>Une <strong>crise réticulocytaire à J7-J10</strong>.</li>\n  <li>Une correction de l'anémie (<strong>augmentation de l'Hb de 1 g/dL/semaine</strong>).</li>\n  <li>Puis normalisation de la microcytose et de l'hypochromie.</li>\n</ul>\nLa <strong>normalisation de la ferritinémie</strong> est le critère d'arrêt du traitement, qui dure généralement <strong>3 à 6 mois</strong> et ne doit pas faire l'objet d'un contrôle de ferritine avant 3 mois."},{"i":"8608fa2b213a","n":219,"o":"219-18","u":"Prise en charge","t":"Connaître les principes du traitement de la carence martiale chez l’adulte et l’enfant","q":"Quand envisager une non-réponse au traitement oral de la carence martiale et quelles en sont les causes ?","a":"Une non-réponse au traitement oral doit faire évoquer plusieurs causes :\n<ul>\n  <li>Une <strong>mauvaise observance</strong> du traitement.</li>\n  <li>Un <strong>défaut d'absorption</strong> du fer (ex : maladies inflammatoires chroniques de l'intestin (MICI), syndrome IRIDA).</li>\n  <li>La persistance d'une microcytose malgré une ferritine normalisée, suggérant une <strong>thalassémie hétérozygote</strong>.</li>\n</ul>\nDans ces situations, ou en cas d'intolérance digestive, d'inefficacité ou de carence profonde, la <strong>voie intraveineuse (IV) ou intramusculaire (IM)</strong> peut être envisagée."},{"i":"a55c95fc0dbc","n":219,"o":"219-18","u":"Prise en charge","t":"Connaître les principes du traitement de la carence martiale chez l’adulte et l’enfant","q":"Comment doit être prise en charge une carence martiale chez l'adulte et l'enfant ?","a":"La prise en charge de la carence martiale repose sur <strong>deux volets indissociables</strong> :\n<ul>\n  <li>Le traitement de la <strong>cause sous-jacente</strong> (ex : retrait d'un DIU, ablation d'un polype, prise en charge d'une ménorragie).</li>\n  <li>La <strong>reconstitution des réserves en fer</strong> de l'organisme.</li>\n</ul>"},{"i":"0fe953310359","n":219,"o":"219-2","u":"Définition","t":"Connaître la définition d’une surcharge en fer","q":"Comment interpréter le Coefficient de Saturation de la Transferrine (CST) dans le diagnostic d'une surcharge en fer ?","a":"<ul><li>Un CST <strong>&gt; 60 %</strong> chez l'<strong>homme</strong> est considéré comme anormal.</li><li>Un CST <strong>&gt; 50 %</strong> chez la <strong>femme</strong> est considéré comme anormal.</li><li>Le diagnostic de surcharge requiert toujours le <strong>couplage ferritine + CST</strong>. Une hyperferritinémie isolée avec un CST normal n'est pas synonyme de surcharge tissulaire (elle peut s'observer dans le syndrome inflammatoire, le syndrome métabolique ou la cytolyse).</li></ul>"},{"i":"4a14b11baab9","n":219,"o":"219-2","u":"Définition","t":"Connaître la définition d’une surcharge en fer","q":"Quelle est la toxicité de l'excès de fer sur l'organisme ?","a":"<p>L'excès de fer est toxique car il <strong>catalyse la conversion du peroxyde d'hydrogène en radicaux libres</strong>. Ces radicaux libres attaquent les membranes cellulaires, les protéines et l'ADN, provoquant des <strong>dommages tissulaires</strong>.</p>"},{"i":"b6b826c2e4a8","n":219,"o":"219-2","u":"Définition","t":"Connaître la définition d’une surcharge en fer","q":"Quel est le mécanisme fondamental de la surcharge en fer ?","a":"<p>Le mécanisme fondamental est l'<strong>absence de voie d'élimination régulée du fer</strong>. L'<strong>absorption intestinale</strong> conditionne donc le stockage, et toute dysrégulation de cette absorption peut entraîner une surcharge.</p>"},{"i":"ce3e729ea94b","n":219,"o":"219-2","u":"Définition","t":"Connaître la définition d’une surcharge en fer","q":"Quelle est la définition d'une surcharge en fer ?","a":"<p>La surcharge en fer est une <strong>accumulation anormale de fer dans l'organisme</strong>, se manifestant biologiquement par une <strong>hyperferritinémie</strong> et, en cas d'atteinte viscérale, par une surcharge tissulaire (particulièrement hépatique).</p>"},{"i":"ef595bbf5ee4","n":219,"o":"219-2","u":"Définition","t":"Connaître la définition d’une surcharge en fer","q":"Quelles sont les valeurs seuils permettant de définir une hyperferritinémie chez l'homme et la femme ?","a":"<ul><li>Chez l'<strong>homme</strong> : ferritinémie <strong>&gt; 300 µg/L</strong>.</li><li>Chez la <strong>femme</strong> : ferritinémie <strong>&gt; 200 µg/L</strong>.</li></ul>"},{"i":"0aaa84ac86c9","n":219,"o":"219-5","u":"Diagnostic positif","t":"Connaître les signes cliniques de la carence martiale","q":"Quels sont les trois signes cliniques généraux de la carence martiale ?","a":"<p>Les trois signes cliniques généraux de la carence martiale sont :</p><ul><li>Une <strong>asthénie</strong>, parfois même sans anémie, corrélée à la ferritinémie.</li><li>Une <strong>fatigabilité musculaire</strong>.</li><li>Une diminution des <strong>performances intellectuelles</strong> (troubles de la mémoire, baisse des performances scolaires).</li></ul>"},{"i":"88fa9beca65a","n":219,"o":"219-5","u":"Diagnostic positif","t":"Connaître les signes cliniques de la carence martiale","q":"Quelles sont les comorbidités cliniques associées à la carence martiale ?","a":"<p>Les comorbidités cliniques associées à la carence martiale incluent :</p><ul><li>Le <strong>syndrome des jambes sans repos</strong>.</li><li>Le <strong>PICA</strong> (géophagie, attirance pour la terre/le plâtre), qui peut être à la fois une cause et une conséquence.</li><li>Le <strong>syndrome de Plummer-Vinson</strong> (ou Kelly-Paterson), caractérisé par l'association d'une anémie par carence martiale, d'une dysphagie et de membranes œsophagiennes.</li></ul>"},{"i":"bf23109aab63","n":219,"o":"219-5","u":"Diagnostic positif","t":"Connaître les signes cliniques de la carence martiale","q":"Quelles sont les principales manifestations cutanéo-muqueuses spécifiquement associées à la carence martiale ?","a":"<p>Les principales manifestations cutanéo-muqueuses spécifiquement associées à la carence martiale sont :</p><ul><li>La <strong>koïlonychie</strong> : ongles fins, striés/fendillés, concaves (signe de carences anciennes).</li><li>Des <strong>rhagades / perlèche</strong> : ulcérations des commissures labiales.</li><li>Une <strong>alopécie non cicatricielle</strong>.</li><li>Une <strong>peau sèche avec prurit diffus</strong> sine materia.</li><li>Une <strong>glossite</strong> et une <strong>dysphagie</strong> par atrophie de la muqueuse œsophagienne, pouvant entraîner des anneaux de striction.</li></ul>"},{"i":"2e20ec8d3b08","n":219,"o":"219-7","u":"Diagnostic positif","t":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","q":"Quelles sont les causes de pertes ou malabsorption devant faire évoquer une carence martiale chez l'enfant ?","a":"<p>Les causes de pertes ou malabsorption devant faire évoquer une carence martiale chez l'enfant sont :</p><ul><li>Un <strong>saignement digestif</strong> (par exemple, un diverticule de Meckel).</li><li>La <strong>maladie cœliaque</strong>.</li><li>Les <strong>MICI</strong> (Maladies Inflammatoires Chroniques de l'Intestin).</li></ul>"},{"i":"86988bfc55ee","n":219,"o":"219-7","u":"Diagnostic positif","t":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","q":"Quels sont les signaux d'appel cliniques devant faire évoquer une carence martiale chez un nourrisson ?","a":"<p>Les signaux d'appel cliniques devant faire évoquer une carence martiale chez un nourrisson, notamment en cas de régime lacté déséquilibré, sont :</p><ul><li>La <strong>pâleur</strong>.</li><li>L'<strong>asthénie</strong>.</li><li>L'<strong>irritabilité</strong>.</li><li>Un <strong>retard ou fléchissement des acquisitions</strong>.</li><li>Des <strong>infections à répétition</strong>.</li></ul>"},{"i":"c7dfb33f226b","n":219,"o":"219-7","u":"Diagnostic positif","t":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","q":"Quelles sont les situations de besoins augmentés devant faire évoquer une carence martiale chez l'enfant ?","a":"<p>Les situations de besoins augmentés devant faire évoquer une carence martiale chez l'enfant sont :</p><ul><li>Une <strong>croissance rapide</strong> du nourrisson et de l'adolescent.</li><li>Chez la fille adolescente, les <strong>pertes menstruelles</strong>.</li></ul>"},{"i":"c95ba2816613","n":219,"o":"219-7","u":"Diagnostic positif","t":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","q":"Quelles sont les situations de réserves initiales insuffisantes devant faire évoquer une carence martiale chez l'enfant ?","a":"<p>Les situations de réserves initiales insuffisantes devant faire évoquer une carence martiale chez l'enfant sont :</p><ul><li>La <strong>prématurité</strong>.</li><li>La <strong>gémellité</strong>.</li><li>L'<strong>hypotrophie</strong> (traduisant une constitution incomplète des réserves en fin de grossesse).</li></ul>"},{"i":"d2bd359e0153","n":219,"o":"219-7","u":"Diagnostic positif","t":"Connaître les situations devant faire évoquer une carence martiale chez l’enfant","q":"Quels sont les contextes d'insuffisance d'apport alimentaire devant faire évoquer une carence martiale chez l'enfant ?","a":"<p>Devant faire évoquer une carence martiale chez l'enfant, les contextes d'insuffisance d'apport alimentaire sont :</p><ul><li>Un <strong>allaitement maternel exclusif ou majoritaire prolongé au-delà de 6 mois</strong> (le lait maternel étant pauvre en fer).</li><li>Une consommation insuffisante de préparations lactées (<strong>moins de 3 fois par jour jusqu'à 1 an</strong>).</li><li>L'absence de <strong>lait de croissance</strong> le cas échéant.</li></ul>"}]};